<?php

declare(strict_types=1);

/**
 * F4b.1 — CLI-only, disposable-database restore rehearsal.
 *
 * NEVER a production updater or automatic recovery. No DbConf, no CMS database
 * connection, no frontend/admin endpoint and no deletion of existing schemas.
 * Archive must have been generated by SiteBackup and must pass independent
 * UpdateRecoveryDataArchive verification before ANY SQL is submitted.
 *
 * This first version deliberately supports SQL dumps <= 32 MiB. Large archives
 * fail closed; streaming and live-host proof belong to later stages.
 */
interface UpdateF4b1RestoreTarget
{
    public function databaseName(): string;
    /** @return list<string> Tables, views, triggers, routines and events. */
    public function existingObjects(): array;
    public function execute(string $sql): void;
    /** @return array<string,int> Table name => count of rows. */
    public function tableRowCounts(): array;
    /** @return list<string> */
    public function triggerNames(): array;
}

/**
 * Optional native environment contract; synthetic targets may use this to
 * verify that compatibility is checked BEFORE the first imported statement.
 * Production integrations must provide an equivalent check before DDL.
 */
interface UpdateF4b1TriggerPreflightTarget
{
    public function assertTriggerCreationCompatible(int $triggerCount): void;
}

/**
 * Pure, read-only trigger environment assessment. No CMS configuration,
 * database connection or global setting changes; never grants privileges.
 */
final class UpdateF4b1TriggerCompatibility
{
    /** @param int|string|bool $binaryLogging @param int|string|bool $trustedCreators */
    public static function assertCompatible(int|string|bool $binaryLogging, int|string|bool $trustedCreators, int $triggerCount): void
    {
        if ($triggerCount < 0) {
            throw new RuntimeException('Invalid trigger inventory.');
        }
        if ($triggerCount === 0) return;
        $logging = self::flag($binaryLogging);
        $trusted = self::flag($trustedCreators);
        if ($logging === null || $trusted === null) {
            throw new RuntimeException('Cannot verify MySQL trigger creation settings.');
        }
        if ($logging && !$trusted) {
            // The native gateway intentionally has no GLOBAL/SUPER privileges.
            throw new RuntimeException('F4b1 trigger restore blocked: binary logging ON and log_bin_trust_function_creators OFF. Import not started.');
        }
    }

    private static function flag(int|string|bool $value): ?bool
    {
        if (is_bool($value)) return $value;
        if (is_int($value)) return $value === 0 ? false : ($value === 1 ? true : null);
        return match (strtoupper($value)) {
            '0', 'OFF', 'FALSE' => false,
            '1', 'ON', 'TRUE' => true,
            default => null,
        };
    }
}

final class UpdateDatabaseIsolatedRestore
{
    private const NAME_PATTERN = '/\Aboilerplate_f4b1_[0-9a-f]{16}\z/D';
    private const MAX_SQL_BYTES = 33554432;
    private const MAX_STATEMENTS = 500000;
    private const MAX_STATEMENT_BYTES = 8388608;

    /**
     * Read/verify the entire backup without creating SQL connections.
     * @return array{status:'review',install_ready:false,tables:int,rows:int,triggers:int,statements:int,sha256:string}
     */
    public function inspect(string $archive): array
    {
        $checked = $this->prepare($archive);
        return [
            'status' => 'review', 'install_ready' => false,
            'tables' => count($checked['tables']),
            'rows' => array_sum($checked['tables']),
            'triggers' => count($checked['triggers']),
            'statements' => count($checked['statements']),
            'sha256' => $checked['sha256'],
        ];
    }

    /**
     * An explicit CLI-only call on a separate, PRE-CREATED, EMPTY F4b1 schema.
     * On failure the disposable schema is left intact for inspection, not
     * silently destroyed or reported as recovered. Never targets DbConf.
     *
     * @return array{status:'isolated_restore_verified',install_ready:false,tables:int,rows:int,triggers:int}
     */
    public function rehearse(string $archive, UpdateF4b1RestoreTarget $target): array
    {
        if (PHP_SAPI !== 'cli') {
            throw new RuntimeException('F4b1 restore is CLI-only.');
        }
        $schema = $target->databaseName();
        if (preg_match(self::NAME_PATTERN, $schema) !== 1) {
            throw new RuntimeException('F4b1 requires a dedicated disposable schema.');
        }
        if ($target->existingObjects() !== []) {
            throw new RuntimeException('F4b1 refuses a non-empty database.');
        }
        $plan = $this->prepare($archive);
        if ($target->databaseName() !== $schema || $target->existingObjects() !== []) {
            throw new RuntimeException('F4b1 target changed during preparation.');
        }
        // The native adapter uses its restricted database connection to read
        // trigger-related server flags BEFORE the first import statement.
        // Synthetic adapters may implement the same fail-closed contract.
        if ($target instanceof UpdateF4b1TriggerPreflightTarget) {
            $target->assertTriggerCreationCompatible(count($plan['triggers']));
        }
        // Do not read the source again after full validation; immutable SQL plan.
        $executing = false;
        try {
            $executing = true;
            foreach ($plan['statements'] as $sql) {
                if ($target->databaseName() !== $schema) {
                    throw new RuntimeException('Selected schema changed during restore.');
                }
                $target->execute($sql);
            }
            $actual = $target->tableRowCounts();
            ksort($actual, SORT_STRING);
            if ($actual !== $plan['tables']) {
                throw new RuntimeException('Post-import table/row inventory mismatch.');
            }
            $actualTriggers = $target->triggerNames();
            sort($actualTriggers, SORT_STRING);
            if ($actualTriggers !== $plan['triggers']) {
                throw new RuntimeException('Post-import trigger inventory mismatch.');
            }
        } catch (Throwable $e) {
            if ($executing) {
                // Never imply that nontransactional MySQL DDL was rolled back.
                try { $target->execute('SET FOREIGN_KEY_CHECKS = 1'); } catch (Throwable $ignored) {}
            }
            throw new RuntimeException('F4b1 isolated restore FAILED. Disposable schema may be partial; keep it isolated.', 0, $e);
        }
        return [
            'status' => 'isolated_restore_verified', 'install_ready' => false,
            'tables' => count($plan['tables']),
            'rows' => array_sum($plan['tables']),
            'triggers' => count($plan['triggers']),
        ];
    }

    /** @return array{sha256:string,tables:array<string,int>,triggers:list<string>,statements:list<string>} */
    private function prepare(string $archive): array
    {
        if (!class_exists('UpdateRecoveryDataArchive')) {
            throw new RuntimeException('Independent recovery archive verifier is unavailable.');
        }
        $checked = (new UpdateRecoveryDataArchive())->verify($archive);
        $canonical = realpath($archive);
        if (!is_string($canonical) || is_link($archive) || !is_file($canonical)) {
            throw new RuntimeException('Unsafe F4b1 archive path.');
        }
        $tar = new PharData($canonical);
        $manifest = json_decode($tar['manifest.json']->getContent(), true, 32, JSON_THROW_ON_ERROR);
        if (!is_array($manifest) || !is_array($manifest['database_tables'] ?? null)
            || !is_int($manifest['database_triggers'] ?? null)
            || !is_int($manifest['database_rows'] ?? null)) {
            throw new RuntimeException('F4b1 requires SiteBackup database inventory.');
        }
        $size = $tar['database.sql']->getSize();
        if (!is_int($size) || $size < 1 || $size > self::MAX_SQL_BYTES) {
            throw new RuntimeException('F4b1 SQL exceeds first-stage safety limit.');
        }
        $sql = $tar['database.sql']->getContent();
        if (strlen($sql) !== $size || strlen($sql) > self::MAX_SQL_BYTES) {
            throw new RuntimeException('F4b1 SQL size changed.');
        }
        // Hash again immediately before parsing. This method does not execute.
        if (!hash_equals($checked['sql_sha256'], hash('sha256', $sql))) {
            throw new RuntimeException('F4b1 SQL checksum mismatch.');
        }
        $tables = $manifest['database_tables'];
        ksort($tables, SORT_STRING);
        if (array_sum($tables) !== $manifest['database_rows']) {
            throw new RuntimeException('F4b1 database row total mismatch.');
        }
        [$statements, $triggers] = $this->parseExporterSql($sql, $tables, $manifest['database_triggers']);
        return [
            'sha256' => $checked['sha256'], 'tables' => $tables,
            'triggers' => $triggers, 'statements' => $statements,
        ];
    }

    /**
     * Bounded parser for SiteBackup's own dump format, NOT a general SQL loader.
     * No executable SQL reaches a target until ALL statements are validated.
     *
     * @param array<string,int> $tables
     * @return array{0:list<string>,1:list<string>}
     */
    private function parseExporterSql(string $sql, array $tables, int $expectedTriggers): array
    {
        if (!str_starts_with($sql, '-- Boilerplate CMS site data backup. RESTORE TO AN EMPTY DATABASE ONLY.\n')) {
            // Use explicit LF in matching below; strict exporter identity.
            if (!str_starts_with($sql, "-- Boilerplate CMS site data backup. RESTORE TO AN EMPTY DATABASE ONLY.\n")) {
                throw new RuntimeException('Unrecognized SiteBackup SQL header.');
            }
        }
        if (str_contains($sql, "\0") || $expectedTriggers < 0) {
            throw new RuntimeException('Invalid SQL dump bytes or trigger inventory.');
        }
        $statements = [];
        $header = [
            'SET NAMES utf8mb4',
            "SET SESSION sql_mode = 'NO_AUTO_VALUE_ON_ZERO'",
            'SET FOREIGN_KEY_CHECKS = 0',
        ];
        $stage = 'header';
        $delimiter = ';';
        $current = '';
        $created = [];
        $rows = array_fill_keys(array_keys($tables), 0);
        $triggers = [];
        $lastTable = null;
        $triggerDelimiterSeen = false;
        $endDelimiterSeen = false;
        $finish = false;
        foreach (explode("\n", $sql) as $line) {
            $trim = trim($line);
            if ($current === '' && ($trim === '' || str_starts_with($trim, '-- '))) continue;
            if ($current === '' && str_starts_with($trim, 'DELIMITER ')) {
                if ($trim === 'DELIMITER $$' && $stage === 'tables' && !$triggerDelimiterSeen && count($created) === count($tables)) {
                    $stage = 'triggers';
                    $delimiter = '$$';
                    $triggerDelimiterSeen = true;
                    continue;
                }
                if ($trim === 'DELIMITER ;' && $stage === 'triggers' && !$endDelimiterSeen) {
                    $stage = 'finish';
                    $delimiter = ';';
                    $endDelimiterSeen = true;
                    continue;
                }
                throw new RuntimeException('Unexpected SQL delimiter directive.');
            }
            if ($finish) throw new RuntimeException('Trailing SQL after final restore guard.');
            $current .= $line . "\n";
            if (strlen($current) > self::MAX_STATEMENT_BYTES) {
                throw new RuntimeException('SQL statement exceeds first-stage size limit.');
            }
            if (!str_ends_with(rtrim($line), $delimiter)) continue;
            $statement = trim(substr(rtrim($current), 0, -strlen($delimiter)));
            $current = '';
            if ($statement === '') throw new RuntimeException('Empty SQL statement.');
            if ($stage !== 'triggers' && self::containsUnquotedSemicolon($statement)) {
                throw new RuntimeException('Unexpected SQL statement separator.');
            }
            if ($stage === 'header') {
                if (count($header) === 0 || $statement !== array_shift($header)) {
                    throw new RuntimeException('Unexpected SQL session prefix.');
                }
                if ($header === []) $stage = 'tables';
            } elseif ($stage === 'tables') {
                if (preg_match('/\ACREATE TABLE `([A-Za-z0-9_]+)` \(/sD', $statement, $m) === 1) {
                    $name = $m[1];
                    if (!array_key_exists($name, $tables) || isset($created[$name])
                        || !preg_match('/\) ENGINE=InnoDB\b/s', $statement)) {
                        throw new RuntimeException('Unexpected table schema in SQL backup.');
                    }
                    $created[$name] = true;
                    $lastTable = $name;
                } elseif (preg_match('/\AINSERT INTO `([A-Za-z0-9_]+)` VALUES \(/sD', $statement, $m) === 1) {
                    $name = $m[1];
                    if (!isset($created[$name]) || $lastTable !== $name || !array_key_exists($name, $rows)
                        || !str_ends_with($statement, ')')) {
                        throw new RuntimeException('Unexpected INSERT target in SQL backup.');
                    }
                    $rows[$name]++;
                    if ($rows[$name] > $tables[$name]) {
                        throw new RuntimeException('Excess rows in SQL backup.');
                    }
                } else {
                    throw new RuntimeException('Unsupported SQL in SiteBackup table section.');
                }
            } elseif ($stage === 'triggers') {
                if (preg_match('/\ACREATE TRIGGER `(media_ref_[A-Za-z0-9_]+)` (BEFORE|AFTER) (INSERT|UPDATE|DELETE) ON `([A-Za-z0-9_]+)` FOR EACH ROW (BEGIN\b.*\bEND)\z/sD', $statement, $m) !== 1
                    || !isset($created[$m[4] ?? '']) || in_array($m[1], $triggers, true)) {
                    throw new RuntimeException('Unsupported or duplicated SiteBackup trigger.');
                }
                // Trigger bodies contain semicolons by design. Only known CMS
                // media guards are supported in this initial isolated stage.
                if (preg_match('/\b(?:DROP|ALTER|TRUNCATE|GRANT|REVOKE|CALL|PREPARE|EXECUTE|OUTFILE|DUMPFILE)\b/i', $m[5])) {
                    throw new RuntimeException('Unsupported trigger operation.');
                }
                $triggers[] = $m[1];
            } elseif ($stage === 'finish') {
                if ($statement !== 'SET FOREIGN_KEY_CHECKS = 1') {
                    throw new RuntimeException('Unexpected SQL ending.');
                }
                $finish = true;
            } else {
                throw new RuntimeException('Unexpected SQL import phase.');
            }
            $statements[] = $statement;
            if (count($statements) > self::MAX_STATEMENTS) {
                throw new RuntimeException('Too many SQL statements.');
            }
        }
        if ($current !== '' || !$finish || !$triggerDelimiterSeen || !$endDelimiterSeen
            || count($created) !== count($tables) || $rows !== $tables || count($triggers) !== $expectedTriggers) {
            throw new RuntimeException('Incomplete SQL backup or manifest inventory mismatch.');
        }
        if (isset($tables['media_reference_state']) && count($triggers) !== 9) {
            throw new RuntimeException('Missing expected CMS media-reference triggers.');
        }
        sort($triggers, SORT_STRING);
        return [$statements, $triggers];
    }

    private static function containsUnquotedSemicolon(string $sql): bool
    {
        $quote = '';
        $length = strlen($sql);
        for ($i = 0; $i < $length; $i++) {
            $c = $sql[$i];
            if ($quote !== '') {
                if ($c === '\\') { $i++; continue; }
                if ($c === $quote) {
                    if ($i + 1 < $length && $sql[$i + 1] === $quote) { $i++; continue; }
                    $quote = '';
                }
                continue;
            }
            if ($c === "'" || $c === '"' || $c === '`') { $quote = $c; continue; }
            if ($c === ';') return true;
        }
        return $quote !== '';
    }
}

/**
 * Optional native MySQL gateway for a PRE-CREATED, EMPTY, LOCAL F4b1 test schema.
 * Requires a dedicated schema-scoped account. Never uses CMS credentials.
 * Do not construct this in normal web/bootstrap requests.
 */
final class UpdateF4b1MysqliTarget implements UpdateF4b1RestoreTarget, UpdateF4b1TriggerPreflightTarget
{
    private mysqli $db;
    private string $schema;

    public function __construct(string $host, string $username, string $password, string $schema, int $port = 3306)
    {
        if (PHP_SAPI !== 'cli' || !in_array($host, ['127.0.0.1', 'localhost'], true)
            || preg_match('/\Aboilerplate_f4b1_[0-9a-f]{16}\z/D', $schema) !== 1
            || $port < 1 || $port > 65535 || $username === '' || strtolower($username) === 'root') {
            throw new RuntimeException('F4b1 requires local MySQL and an isolated named schema/account.');
        }
        if (class_exists('DbConf', false)
            && ($schema === DbConf::name() || $username === DbConf::user())) {
            throw new RuntimeException('Active CMS credentials are forbidden for F4b1.');
        }
        $connection = new mysqli($host, $username, $password, $schema, $port);
        try {
            if (!$connection->set_charset('utf8mb4')) {
                throw new RuntimeException('Cannot set F4b1 connection charset.');
            }
            $this->db = $connection;
            $this->schema = $schema;
            if ($this->databaseName() !== $schema) {
                throw new RuntimeException('Selected F4b1 schema mismatch.');
            }
            $this->assertSchemaOnlyGrants();
        } catch (Throwable $e) {
            $connection->close();
            throw $e;
        }
    }

    public function __destruct()
    {
        if (isset($this->db)) $this->db->close();
    }

    public function databaseName(): string
    {
        $r = $this->db->query('SELECT DATABASE()');
        return (string)($r->fetch_row()[0] ?? '');
    }

    /**
     * Fail closed before importing SQL if this limited account cannot create
     * backup triggers under server-level binary logging requirements.
     */
    public function assertTriggerCreationCompatible(int $triggerCount): void
    {
        if ($triggerCount < 0) throw new RuntimeException('Invalid trigger inventory.');
        if ($triggerCount === 0) return;
        if ($this->databaseName() !== $this->schema) {
            throw new RuntimeException('F4b1 target changed before trigger preflight.');
        }
        try {
            $result = $this->db->query('SELECT @@GLOBAL.log_bin, @@GLOBAL.log_bin_trust_function_creators');
            $flags = $result->fetch_row();
            $result->free();
            if (!is_array($flags) || count($flags) !== 2) {
                throw new RuntimeException('MySQL trigger setting snapshot unavailable.');
            }
            UpdateF4b1TriggerCompatibility::assertCompatible(
                (string)$flags[0], (string)$flags[1], $triggerCount
            );
        } catch (mysqli_sql_exception $e) {
            // No SQL text or credentials in user-facing errors; keep the
            // original exception for code/SQLSTATE diagnostics in CLI QA.
            throw new RuntimeException('Cannot inspect F4b1 MySQL trigger settings.', 0, $e);
        }
    }

    public function existingObjects(): array
    {
        $queries = [
            'SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE()',
            'SELECT TRIGGER_NAME FROM INFORMATION_SCHEMA.TRIGGERS WHERE TRIGGER_SCHEMA = DATABASE()',
            'SELECT ROUTINE_NAME FROM INFORMATION_SCHEMA.ROUTINES WHERE ROUTINE_SCHEMA = DATABASE()',
            'SELECT EVENT_NAME FROM INFORMATION_SCHEMA.EVENTS WHERE EVENT_SCHEMA = DATABASE()',
        ];
        $objects = [];
        foreach ($queries as $sql) {
            foreach ($this->db->query($sql)->fetch_all(MYSQLI_NUM) as $r) {
                $objects[] = (string)$r[0];
            }
        }
        return $objects;
    }

    public function execute(string $sql): void
    {
        if ($this->databaseName() !== $this->schema) {
            throw new RuntimeException('Selected schema changed.');
        }
        $this->db->query($sql);
    }

    public function tableRowCounts(): array
    {
        $rows = $this->db->query('SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_TYPE = \'BASE TABLE\'')->fetch_all(MYSQLI_NUM);
        $result = [];
        foreach ($rows as $row) {
            $name = (string)$row[0];
            if (preg_match('/\A[A-Za-z0-9_]+\z/D', $name) !== 1) {
                throw new RuntimeException('Unexpected F4b1 table identifier.');
            }
            $count = $this->db->query('SELECT COUNT(*) FROM `' . $name . '`')->fetch_row()[0];
            $result[$name] = (int)$count;
        }
        return $result;
    }

    public function triggerNames(): array
    {
        $rows = $this->db->query('SELECT TRIGGER_NAME FROM INFORMATION_SCHEMA.TRIGGERS WHERE TRIGGER_SCHEMA = DATABASE()')->fetch_all(MYSQLI_NUM);
        return array_map(static fn(array $row): string => (string)$row[0], $rows);
    }

    private function assertSchemaOnlyGrants(): void
    {
        $grants = $this->db->query('SHOW GRANTS FOR CURRENT_USER()')->fetch_all(MYSQLI_NUM);
        $allowed = ['`' . $this->schema . '`.*', $this->schema . '.*'];
        $hasSchemaGrant = false;
        if ($grants === []) throw new RuntimeException('Cannot verify F4b1 MySQL privileges.');
        foreach ($grants as $row) {
            $grant = (string)$row[0];
            if (stripos($grant, 'WITH GRANT OPTION') !== false
                || preg_match('/\b(?:PROXY|ROLE_ADMIN|SYSTEM_USER|SUPER|FILE)\b/i', $grant)) {
                throw new RuntimeException('F4b1 MySQL account is too privileged.');
            }
            if (!preg_match('/\AGRANT\s+.+?\s+ON\s+(.+?)\s+TO\s+/i', $grant, $m)) {
                throw new RuntimeException('F4b1 forbids MySQL roles and unrecognized grants.');
            }
            if ($m[1] === '*.*' && preg_match('/\AGRANT USAGE ON /i', $grant)) continue;
            if (!in_array($m[1], $allowed, true)) {
                throw new RuntimeException('F4b1 account has privileges outside disposable schema.');
            }
            $hasSchemaGrant = true;
        }
        if (!$hasSchemaGrant) throw new RuntimeException('F4b1 requires database-scoped restore privileges.');
    }
}
